class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        from collections import Counter

        count = Counter(digits)
        total = 0

        # Try each possible hundreds digit (1-9)
        for h in range(1, 10):
            if count[h] == 0:
                continue
            count[h] -= 1
            # Try each possible tens digit (0-9)
            for t in range(0, 10):
                if count[t] == 0:
                    continue
                count[t] -= 1
                # Try each possible units digit (0,2,4,6,8)
                for u in range(0, 10, 2):
                    if count[u] > 0:
                        total += 1
                count[t] += 1
            count[h] += 1

        return total
```

