N = int(input())

if N == 1:
    print("=")
elif N == 2:
    print("==")
else:
    # For N >= 3, the string has exactly one '=' in the middle if N is odd,
    # or two adjacent '='s in the middle if N is even.
    if N % 2 == 1:
        # Odd length: one '=' in the center
        mid = N // 2
        s = [''] * N
        for i in range(N):
            if i == mid:
                s[i] = '='
            else:
                s[i] = '-'
        print(''.join(s))
    else:
        # Even length: two adjacent '='s in the center
        mid1 = N // 2 - 1
        mid2 = N // 2
        s = [''] * N
        for i in range(N):
            if i == mid1 or i == mid2:
                s[i] = '='
            else:
                s[i] = '-'
        print(''.join(s))
